-- Original editorial curriculum; additive seed, existing rows are never overwritten.
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002201','primeira-partida','Primeira partida: objetivo, lobby e modalidades','lesson','decisions','Entenda o objetivo antes de escolher uma fila ou copiar uma rotina avançada.','Ponto de partida. Battle Royale é uma disputa de sobrevivência: o objetivo é chegar ao final como a última pessoa ou equipe restante. Uma eliminação pode abrir espaço, mas correr atrás de toda luta pode prejudicar esse objetivo. Fortnite também reúne experiências que não seguem esse formato. Antes de estudar um guia, identifique exatamente o modo a que ele se refere.

No lobby, leia o nome da experiência e o tamanho da equipe. Confira se há construção, se a fila é ranqueada e se o preenchimento de equipe está ativo. Os rótulos e caminhos da interface podem mudar. Na primeira sessão, escolha uma experiência compreensível, sem obrigação de competir. Não confunda o nível de conta, o passe ou cosméticos com habilidade demonstrada.

Uma partida pode ser estudada como chegada ao mapa, obtenção de recursos, deslocamentos, confrontos e disputa final. Early, mid e endgame são nomes úteis para falar dessas situações, não horários universais. Uma partida curta pode terminar antes de você observar todas elas. Em Reload, as possibilidades de retorno alteram essa sequência; haverá uma aula própria.

Atividade editorial. Abra o lobby e anote experiência, tamanho da equipe e objetivo. Em seguida, acompanhe uma partida sua ou uma explicação oficial e identifique chegada, primeiro recurso, primeira decisão e motivo do encerramento. Não é necessário sobreviver até o fim para concluir este estudo.

Antes de avançar. Explique com suas palavras a diferença entre entrar numa partida, vencer uma luta e vencer o Battle Royale. Se não souber localizar uma opção, consulte o suporte da Epic para seu dispositivo; não forneça senha ou credenciais ao Clutchfolio.','Curadoria Clutchfolio','https://store.epicgames.com/p/fortnite','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['foundations','foundation','nivel-0']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":0,"domain":"foundations","modes":["build","zero"],"experience":"all","phase":"foundation","prerequisites":[],"objectives":["Identificar experiência e objetivo da partida.","Distinguir sobrevivência, confronto e vitória."],"assessment":["Descrever a modalidade escolhida sem depender do nome de um criador.","Anotar uma decisão observada e o motivo do fim da partida."],"exercise_ids":[],"competency_ids":[],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"Fortnite — Epic Games Store","url":"https://store.epicgames.com/p/fortnite","kind":"official","access":"page","supports":"Objetivo do Battle Royale e distinção entre experiências. A listagem contém também textos históricos; não confirma todos os detalhes da interface atual."},{"title":"Controles no PC e console — suporte Epic","url":"https://www.epicgames.com/help/c-34254770/c-37371353/a10326284?lang=pt-BR","kind":"official","access":"page","supports":"Localização das configurações por dispositivo e dependência da modalidade; não recomenda uma sensibilidade ideal."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002202','controles-interface','Controles, câmera e leitura da interface','lesson','decisions','Monte uma referência pessoal dos comandos e aprenda a ler os recursos visíveis.','Conhecer os comandos vem antes de medir velocidade. Nas configurações, encontre a seção do seu dispositivo e da modalidade selecionada. Anote ações de movimentar, olhar, interagir, trocar item, abrir inventário, marcar informação e, quando houver construção, colocar, editar e resetar peças. Este texto não fixa teclas: layouts e opções de acessibilidade variam.

Faça uma mudança por vez. Uma sensibilidade copiada de um profissional não comprova adequação ao seu dispositivo ou tarefa. Registre a configuração declarada se pretende comparar testes; uma alteração relevante cria uma nova condição de comparação. Ajuste conforto e legibilidade antes de tentar acelerar. Nenhuma configuração elimina a necessidade de observar e decidir.

Interface. Localize os indicadores de vida, escudo, munição, recursos, equipe, mapa e tempestade disponíveis naquela experiência. Vida e diferentes proteções não devem ser somadas mentalmente sem entender o que a modalidade oferece. Leia o inventário para saber qual item está selecionado, o que pode ser usado agora e o que precisa ser recarregado ou substituído. Não memorizamos valores de dano ou regeneração sem versão confirmada.

Atividade editorial. Em ambiente sem pressão, diga o nome da ação antes de executá-la. Observe onde sua câmera aponta ao movimentar e ao trocar item. Depois descreva uma captura da sua interface: quais recursos existem, qual está baixo e qual informação está ausente? Quando não houver um indicador conhecido, investigue a modalidade antes de assumir um erro.

Critério de avanço. Conseguir localizar os comandos e explicar a interface é diferente de executar bem sob pressão. Guarde essa distinção para seus registros. Dor, desconforto ou perda de atenção são motivos para ajustar ou interromper a atividade, não para aumentar a duração.','Curadoria Clutchfolio','https://www.epicgames.com/help/c-34254770/c-37371353/a10326284?lang=pt-BR','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['foundations','foundation','nivel-0']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":0,"domain":"foundations","modes":["build","zero"],"experience":"all","phase":"foundation","prerequisites":["primeira-partida"],"objectives":["Localizar comandos e indicadores do próprio dispositivo.","Registrar configurações para comparações consistentes."],"assessment":["Demonstrar troca de item, interação e marcação sem uma tecla prescrita.","Explicar os recursos visíveis e uma informação ausente."],"exercise_ids":[],"competency_ids":["movement"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"Controles no PC e console — suporte Epic","url":"https://www.epicgames.com/help/c-34254770/c-37371353/a10326284?lang=pt-BR","kind":"official","access":"page","supports":"Localização das configurações por dispositivo e dependência da modalidade; não recomenda uma sensibilidade ideal."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002203','inventario-tempestade','Inventário, recursos e tempestade','lesson','decisions','Transforme os indicadores da partida em decisões, sem decorar números antigos.','Um inventário é um conjunto de opções. Antes de pegar um item, pergunte qual necessidade ele atende, se há recurso para utilizá-lo e qual opção será perdida na troca. Arma, cura e mobilidade não têm o mesmo papel. A composição exata depende dos itens disponíveis; não existe loadout universal nesta aula.

A tempestade cria restrições de espaço e tempo. Leia o mapa, a área segura e os indicadores da fase atual. Estar dentro da zona não significa estar protegido de adversários. Estar fora dela não informa sozinho quanto tempo resta para chegar: distância, terreno, exposição e recursos interferem. Não usamos uma tabela fixa de dano, velocidade ou círculos de temporadas antigas.

Antes de deslocar, confira recursos relevantes, próxima cobertura, opções de movimento e informação sobre oponentes. Durante o trajeto, atualize a leitura. Se um caminho ficou bloqueado, não continue apenas porque ele estava no plano inicial. Em equipe, comunique a mudança e confirme se os demais ainda conseguem acompanhar.

Atividade editorial. Pause uma gravação antes de uma troca de item ou rotação. Escreva o problema que a ação pretende resolver, duas alternativas e uma informação que você gostaria de ter. Retome o vídeo e veja o que ocorreu. Um final positivo não transforma automaticamente uma escolha arriscada em boa decisão.

Registro. Anote modalidade, versão ou data, itens relevantes, tempo percebido e decisão. Compare a qualidade das justificativas em situações parecidas. Contar quantos itens você coletou ou quantos minutos ficou vivo mede volume, não compreensão. A avaliação é conseguir explicar uma troca e um deslocamento usando as informações então disponíveis.','Curadoria Clutchfolio','https://store.epicgames.com/p/fortnite','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['foundations','foundation','nivel-1']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":1,"domain":"foundations","modes":["build","zero"],"experience":"all","phase":"foundation","prerequisites":["controles-interface"],"objectives":["Relacionar inventário a necessidades da partida.","Ler restrições de espaço e tempo antes de mover."],"assessment":["Justificar uma troca de item e uma alternativa descartada.","Separar informação disponível de conhecimento obtido depois."],"exercise_ids":[],"competency_ids":["resources","information"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"Fortnite — Epic Games Store","url":"https://store.epicgames.com/p/fortnite","kind":"official","access":"page","supports":"Objetivo do Battle Royale e distinção entre experiências. A listagem contém também textos históricos; não confirma todos os detalhes da interface atual."},{"title":"Guia do Modo Ranqueado — Epic","url":"https://www.fortnite.com/competitive/discover-competitive/fortnite-ranked-play-explained?lang=pt-BR&region=NAC","kind":"official","access":"page","supports":"Experiências ranqueadas e orientação de acesso. Não fornece fórmula reproduzível de pontos; não usamos tabela histórica como requisito universal."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002204','materiais-mats','Mats: madeira, pedra, metal e economia de construção','lesson','decisions','Entenda o que os materiais permitem fazer e quais parâmetros precisam de nova verificação.','Mats é o nome comum para materiais de construção. Madeira, pedra e metal são recursos usados em construção; em ilhas do Criativo também podem funcionar como moeda ou requisito de dispositivos. A documentação oficial permite configurações diferentes de disponibilidade e recursos infinitos. Portanto, um treino em ilha não prova que você teria os mesmos recursos numa partida competitiva.

Observe coleta, saldo e consumo na experiência praticada. Um material pode ter comportamento de construção distinto de outro, mas resistência, tempo de formação, limites de armazenamento e custo devem ser verificados naquela versão. Esta aula não publica valores atuais desses parâmetros porque a pesquisa não os confirmou de forma suficiente para todas as modalidades. Não trate tabelas históricas como regra vigente.

Economia editorial. Separe três problemas: obter recursos, gastar recursos para resolver uma situação e manter opções para o que vem depois. Construir uma proteção útil e repetir peças sem propósito têm custos diferentes. Uma rotação que parece segura pode deixar poucas opções para a próxima zona. Antes de gastar, identifique qual linha de visão, caminho ou espaço a peça deve controlar.

Em equipe, diga o recurso necessário e o que a troca permite fazer. Distribuição não exige que todos tenham saldos iguais: necessidades imediatas e tarefas podem diferir. Combine a entrega e confirme o recebimento; não suponha que o colega percebeu sua falta de materiais.

Atividade. Registre uma sequência curta em que os saldos sejam visíveis. Marque proteção necessária, gasto evitável e oportunidade de reposição. Refaça o planejamento com os recursos realmente disponíveis. Em Construção Zero, esta sequência não é um pré-requisito: estude cobertura, mobilidade e recursos da modalidade própria.','Curadoria Clutchfolio','https://dev.epicgames.com/documentation/en-us/fortnite/using-world-resource-items-in-fortnite-creative','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['resources','foundation','nivel-1']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":1,"domain":"resources","modes":["build"],"experience":"all","phase":"foundation","prerequisites":["inventario-tempestade"],"objectives":["Distinguir obtenção, consumo e reserva de mats.","Identificar parâmetros que variam por versão e ilha."],"assessment":["Explicar o propósito de uma peça e o custo de mantê-la.","Registrar um gasto evitável sem presumir um limite universal."],"exercise_ids":[],"competency_ids":["resources","building"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"World Resource Items — documentação Epic","url":"https://dev.epicgames.com/documentation/en-us/fortnite/using-world-resource-items-in-fortnite-creative","kind":"official","access":"page","supports":"Madeira, pedra e metal; parâmetros de recursos configuráveis em ilhas. Não estabelece limites nem resistência atuais do Battle Royale."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002205','pecas-edicao','Peças, edição e reset: a base da construção','lesson','mechanics','Aprenda a função de paredes, rampas, pisos e cones antes de combiná-los.','Trate parede, rampa, piso e cone como ferramentas de espaço. Uma parede pode interromper uma linha de visão; rampa e piso podem alterar acesso e apoio; um cone pode restringir uma trajetória. O efeito depende da posição, da propriedade da peça e do que o adversário consegue fazer. Colocar mais peças não equivale a controlar melhor uma situação.

Edição modifica uma peça; reset busca retornar à sua configuração original quando permitido. Observe seleção, confirmação, orientação da câmera e possibilidade de movimento antes de buscar velocidade. Uma abertura pode permitir seu disparo e também expor você. Um reset tardio pode encerrar sua própria saída. O objetivo inicial é executar a sequência com intenção e verificar o estado da peça.

Atividade introdutória. Escolha uma sequência simples que exista na ilha ou ambiente utilizado: colocar uma peça, abrir uma passagem, atravessar e resetar. Registre a sequência e as opções. Repita somente enquanto consegue observar o que errou. Este procedimento é editorial; não afirmamos ter executado as ilhas nem que qualquer percurso específico permaneça disponível.

Atividade intermediária. Acrescente um alvo ou restrição de posicionamento, mantendo o mesmo percurso. Atividade avançada. Compare quando a sequência ajuda numa situação de combate e quando seria melhor não editar. São perguntas de estudo, não desbloqueios obrigatórios.

Métrica. Conte falhas ou registre tempo somente num percurso identificável, com o mesmo cenário e condições. Se a sequência muda, mantenha os registros separados. Freebuild permite explorar combinações; Edit Course restringe um percurso. Nenhum dos dois, isoladamente, comprova decisão correta diante de um adversário.','Curadoria Clutchfolio','https://www.fortnite.com/@raider464/2424-4344-7824','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['building','foundation','nivel-2']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":2,"domain":"building","modes":["build"],"experience":"all","phase":"foundation","prerequisites":["controles-interface","materiais-mats"],"objectives":["Relacionar tipos de peça a proteção e acesso.","Executar e explicar uma edição seguida de reset."],"assessment":["Registrar percurso e falhas para comparação compatível.","Identificar uma abertura que também expõe o jogador."],"exercise_ids":["00000000-0000-4000-8000-000000001001","00000000-0000-4000-8000-000000001002"],"competency_ids":["building","editing","reset"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"Mechanics Training V5 — Raider464","url":"https://www.fortnite.com/@raider464/2424-4344-7824","kind":"official","access":"listing","supports":"Código e categorias anunciadas pelo criador: edição, mira, peeks, box fighting e piece control. Não é teste funcional nem prova de transferência."},{"title":"Training Hub V2 — Reisshub","url":"https://www.fortnite.com/@reisshub/4175-6046-6184","kind":"official","access":"listing","supports":"Identidade e código da ilha de treinamento. Os procedimentos desta aula são editoriais; a ilha não foi executada."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002206','mira-movimento','Mira (Aim), movimentação e crosshair placement','lesson','competitive','Diferencie acompanhar um alvo, corrigir a mira e preparar o próximo ângulo.','Tracking é acompanhar o movimento do alvo. Flick é uma correção rápida de direção; microcorrection é um ajuste menor. Target switching envolve mudar a atenção e a mira entre alvos. Crosshair placement trata da posição da mira antes de precisar corrigir. Esses problemas se relacionam, mas uma pontuação de tracking não mede todos eles.

Comece pela tarefa. Para shotgun, defina distância e momento do disparo; para acompanhar movimento, observe continuidade e perda do alvo. Não conclua que uma técnica é melhor apenas porque parece rápida num vídeo. A movimentação do jogador modifica o ângulo e a exposição, e a arma ou cenário pode modificar as condições do teste.

Atividade editorial isolada. Escolha um cenário realmente disponível e mantenha arma, alvo, opções e dispositivo constantes. Registre a métrica exibida, se houver. Se a ilha não oferecer o cenário ou indicador, não invente pontuação: use observações e descreva a tarefa. A listagem de um hub não confirma todas as métricas internas.

Aplicação. Reveja uma luta e pause antes de o adversário aparecer. Onde a mira já estava? Qual deslocamento abriu a linha de visão? O erro foi perder o alvo, selecionar um ângulo ruim ou disparar no momento errado? Mais de uma explicação pode ser plausível; marque hipóteses em vez de declarar causa sem evidência.

Avaliação. Compare testes equivalentes e depois procure aplicação em situações semelhantes de partida. Melhorar num cenário não prova transferência universal. A revisão científica sobre aprendizagem em esportes ajuda a formular perguntas sobre retenção e transferência, mas não valida este exercício especificamente em Fortnite.','Curadoria Clutchfolio','https://www.fortnite.com/@reisshub/4175-6046-6184','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['fight','foundation','nivel-2']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":2,"domain":"fight","modes":["build","zero"],"experience":"all","phase":"foundation","prerequisites":["controles-interface","inventario-tempestade"],"objectives":["Distinguir tracking, correção e preparação da mira.","Separar erro de execução de hipótese tática."],"assessment":["Descrever um teste com cenário e condições estáveis.","Identificar a posição da mira antes de uma exposição."],"exercise_ids":[],"competency_ids":["tracking","crosshair","moving-aim"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"Training Hub V2 — Reisshub","url":"https://www.fortnite.com/@reisshub/4175-6046-6184","kind":"official","access":"listing","supports":"Identidade e código da ilha de treinamento. Os procedimentos desta aula são editoriais; a ilha não foi executada."},{"title":"Intervenções de aquisição de habilidades — revisão de escopo","url":"https://pubmed.ncbi.nlm.nih.gov/38401870/","kind":"scientific","access":"abstract","supports":"Mapeia intervenções e limitações de retenção/transferência em esportes; adaptação ao Fortnite é editorial."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002207','peeks-trocas','Peeks, timing e trocas protegidas','lesson','competitive','Estude o ângulo e a saída antes de avaliar apenas o dano causado.','Peek é uma exposição para obter informação ou oportunidade de ação. A câmera em terceira pessoa torna relevante a relação entre personagem, cobertura e adversário. Right-hand peek descreve uma organização de ângulo associada ao lado direito; não significa invulnerabilidade. Distância da cobertura, posição do oponente e tempo de exposição mudam o resultado.

Prefire é antecipar uma oportunidade de disparo a partir de uma leitura, não atirar aleatoriamente em toda abertura. Timing é escolher o momento relativo a ações e recursos: quando o outro recarrega, quando uma peça abre ou quando você pode recuar. A interpretação precisa de informação observável. Se não havia sinal suficiente, registre a decisão como arriscada ou incerta.

Atividade editorial. Reveja duas trocas e anote cobertura, posição da câmera, caminho de saída, dano observado e informações anteriores ao disparo. Compare os ângulos disponíveis. Em Construção, inclua edição e reset; em Construção Zero, use a cobertura existente e a possibilidade de reposicionamento. Nenhum jogador precisa estudar edição para aplicar a leitura de exposição em Zero Build.

Em prática com outra pessoa, combine uma situação simples e uma pergunta, como identificar uma saída antes de se expor. Não transfira para o jogo garantias absolutas de um artigo. A explicação de Dignitas serve como análise técnica documentada; nosso procedimento e critério são editoriais.

Critério. Explique por que uma troca era possível e como encerrá-la. Diferencie dano causado, dano recebido e custo de continuar. Uma eliminação não apaga uma exposição evitável, assim como receber dano não prova sozinho que a decisão foi ruim.','Curadoria Clutchfolio','https://dignitas.gg/articles/right-hand-peeks-are-op-and-here-is-how-you-abuse-them','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['fight','mid','nivel-3']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":3,"domain":"fight","modes":["build","zero"],"experience":"all","phase":"mid","prerequisites":["mira-movimento"],"objectives":["Relacionar ângulo, exposição e recuo.","Interpretar timing com informação disponível."],"assessment":["Comparar duas trocas sem afirmar proteção absoluta.","Propor uma saída antes de executar o confronto."],"exercise_ids":["00000000-0000-4000-8000-000000001006"],"competency_ids":["trades","fight-selection"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"Right-hand peeks — Dignitas","url":"https://dignitas.gg/articles/right-hand-peeks-are-op-and-here-is-how-you-abuse-them","kind":"professional","access":"page","supports":"Explicação de câmera, cobertura e distância ao ângulo. Afirmações absolutas do autor não são adotadas como garantias."},{"title":"Replays e versões — suporte Epic","url":"https://www.epicgames.com/help/c-34254770/c-33726977/a25553277?lang=pt-BR","kind":"official","access":"page","supports":"Revisão de partidas e limitações de versão/plataforma. Reprodução de arquivos não foi testada nesta pesquisa."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002208','piece-box-realistic','Piece Control, Box Fight e Realistic: do espaço à decisão','lesson','competitive','Combine propriedade de peças e leitura do adversário sem confundir drill com partida.','Piece Control é estudar como peças e posições limitam as opções de movimento. Controle de espaço não termina ao colocar uma peça: verifique quem pode editar, onde o adversário pode sair e se você ficou exposto. Prever uma trajetória é trabalhar com sinais e alternativas, não saber com certeza o próximo movimento.

Box Fight concentra confrontos em espaços delimitados por construção. Realistic busca praticar situações com contexto de combate; regras, recursos e fidelidade dependem da experiência escolhida. Um 1v1 pode isolar um problema, mas não reproduz automaticamente terceiros, rotação, equipe ou pontuação de torneio. Leia as condições da atividade antes de interpretar seu resultado.

Prática inicial. Identifique uma saída do adversário e quais peças seriam relevantes para controlá-la. Execute devagar, mantendo uma proteção e uma saída próprias. Prática contextual. Com outra pessoa, combine uma situação e varie a resposta do defensor. Observe se você adapta a decisão em vez de repetir a mesma sequência independentemente do contexto.

Retakes buscam recuperar uma posição ou vantagem de altura, mas gastar recursos para subir pode ser inadequado. Compare a opção de disputar height com continuar num espaço mais protegido. Não transforme uma sequência popular de Freebuild em resposta obrigatória para toda luta.

Registro. Separe erro de peça, leitura de movimento, exposição e decisão de continuar. Use os exercícios reais do catálogo sem mudar a unidade de resultados anteriores. A revisão identifica um problema para a próxima sessão; ganhar mais duelos ou acumular horas não prova que todos os componentes melhoraram.','Curadoria Clutchfolio','https://www.fortnite.com/@jivantv/7037-5244-5527','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['fight','mid','nivel-3']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":3,"domain":"fight","modes":["build"],"experience":"all","phase":"mid","prerequisites":["pecas-edicao","peeks-trocas"],"objectives":["Identificar propriedade, saídas e proteção ao controlar peças.","Distinguir drill, duelo e contexto de partida."],"assessment":["Registrar uma leitura correta e uma alternativa ignorada.","Justificar disputar ou abandonar uma posição de altura."],"exercise_ids":["00000000-0000-4000-8000-000000001003","00000000-0000-4000-8000-000000001004","00000000-0000-4000-8000-000000001101"],"competency_ids":["piece-ownership","prediction","box-fight","realistic"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"How To Piece Control — JivanTV","url":"https://www.fortnite.com/@jivantv/7037-5244-5527","kind":"official","access":"listing","supports":"Ilha de exercícios de piece control, do básico ao avançado; tutoriais anunciados não foram assistidos."},{"title":"Mechanics Training V5 — Raider464","url":"https://www.fortnite.com/@raider464/2424-4344-7824","kind":"official","access":"listing","supports":"Código e categorias anunciadas pelo criador: edição, mira, peeks, box fighting e piece control. Não é teste funcional nem prova de transferência."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002209','early-drop','Early game: drop, loot e plano alternativo','lesson','decisions','Prepare a chegada ao mapa com informação e contingências, sem rotas de loot inventadas.','Early game é o conjunto de decisões da chegada e estabilização inicial. Um drop é uma intenção de pouso; POI é um ponto de interesse. A rota real depende do mapa e das condições da partida. Não existe aqui uma lista de locais atuais, baús garantidos ou melhor drop: esses detalhes exigem inspeção da temporada e fonte específica.

Antes da partida, escolha o que observar: terreno, caminhos, opções de recurso e possibilidade de contestação. Na chegada, atualize o plano com o que realmente viu. Um recurso esperado pode não estar disponível. Defina uma alternativa para pouso desfavorável e uma condição para abandonar o confronto inicial. Reconhecer desvantagem não significa que toda retirada será possível.

Off-spawn fight é uma luta do início da partida, com recursos e informações ainda limitados. Avalie o item disponível, proteção e caminhos de saída antes de perseguir alguém. Em equipe, confirme onde cada pessoa caiu e o que consegue fazer agora. Um plano conjunto falha se pressupõe que todos receberam o mesmo loot.

Atividade editorial. Pause a gravação na descida, no primeiro recurso e na primeira decisão de confronto. Anote o plano inicial, uma informação nova e a adaptação feita. Desenhe uma rota alternativa usando apenas o mapa observado. Em Solo, você administra suas próprias tarefas; em Duplas ou Trios disponíveis, distribua observação e comunicação sem presumir papéis rígidos.

Transição. Considere encerrado o problema inicial quando consegue explicar a situação, organizar os recursos e decidir como seguir para a zona ou próxima posição. Isso é um critério editorial de estudo, não uma fase oficial com minuto fixo.','Curadoria Clutchfolio','https://store.epicgames.com/p/fortnite','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['phases','early','nivel-3']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":3,"domain":"phases","modes":["build","zero"],"experience":"all","phase":"early","prerequisites":["inventario-tempestade"],"objectives":["Planejar chegada e uma alternativa condicionada ao mapa.","Reavaliar o confronto inicial com recursos reais."],"assessment":["Comparar plano de pouso e informação obtida na chegada.","Definir uma condição de saída e transição para rotação."],"exercise_ids":["00000000-0000-4000-8000-000000001006"],"competency_ids":["offspawn","information","resources"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"Fortnite — Epic Games Store","url":"https://store.epicgames.com/p/fortnite","kind":"official","access":"page","supports":"Objetivo do Battle Royale e distinção entre experiências. A listagem contém também textos históricos; não confirma todos os detalhes da interface atual."},{"title":"Como Khanada pratica em 2026 — entrevista Dignitas","url":"https://dignitas.gg/articles/how-fortnite-pros-actually-practice-in-2026-featuring-khanada","kind":"professional","access":"page","supports":"Relato individual de aquecimento, prática e análise. Não estabelece rotina universal, dose ótima ou papéis fixos de uma equipe."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002210','mid-rotacoes','Mid game: rotação, posicionamento e escolha de fights','lesson','decisions','Avalie caminhos, tempo e informação antes de transformar uma rotação em confronto.','Rotação é o deslocamento planejado para uma posição útil diante das restrições da partida. Não é simplesmente correr na direção do centro. Compare distância, terreno, linhas de visão, recursos, tempo e informação sobre outros jogadores. Uma rota curta pode expor mais; uma rota longa pode consumir a janela disponível. A decisão continua válida apenas enquanto suas condições persistem.

Deadside é uma hipótese de lado com menor concentração ou pressão relativa. Sem visão completa, você não conhece todos os jogadores. Marque o que foi observado e o que foi inferido. Posicionamento inclui o lugar e as opções que ele oferece: visão, cobertura, entrada, saída e capacidade de acompanhar a próxima mudança.

Escolha de fights. Pergunte o que a luta resolve, o custo previsto e a possibilidade de terceiros. Um adversário aparentemente isolado pode receber apoio. Não existe regra universal de sempre evitar ou sempre buscar combate. O objetivo da partida e, em torneios, a pontuação verificada alteram incentivos, sem eliminar a necessidade de avaliar risco.

Em Solo, informação e execução se concentram numa pessoa. Em Duplas, uma decisão precisa ser comunicada e acompanhada. Em Trios, quando a fila existir, mais integrantes podem observar ângulos e também se separar. Compare distância entre jogadores e possibilidade de apoio; não assuma que maior equipe torna a rotação automaticamente segura.

Atividade. Pause antes de mover, desenhe duas rotas e declare suas condições de escolha. Retome e observe a primeira informação que exigiria reavaliação. Registre se a equipe entendeu o plano antes da execução. A avaliação é a justificativa e atualização, não o resultado final isolado.','Curadoria Clutchfolio','https://dignitas.gg/articles/how-fortnite-pros-actually-practice-in-2026-featuring-khanada','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['phases','mid','nivel-4']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":4,"domain":"phases","modes":["build","zero"],"experience":"all","phase":"mid","prerequisites":["early-drop","peeks-trocas"],"objectives":["Comparar rotas por terreno, tempo e exposição.","Tratar deadside como leitura contextual, não certeza."],"assessment":["Descrever duas rotas e condições para mudar o plano.","Identificar uma comunicação necessária antes do movimento."],"exercise_ids":["00000000-0000-4000-8000-000000001006","00000000-0000-4000-8000-000000001104"],"competency_ids":["rotation","deadside","positioning","fight-selection"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"Como Khanada pratica em 2026 — entrevista Dignitas","url":"https://dignitas.gg/articles/how-fortnite-pros-actually-practice-in-2026-featuring-khanada","kind":"professional","access":"page","supports":"Relato individual de aquecimento, prática e análise. Não estabelece rotina universal, dose ótima ou papéis fixos de uma equipe."},{"title":"Replays e versões — suporte Epic","url":"https://www.epicgames.com/help/c-34254770/c-33726977/a25553277?lang=pt-BR","kind":"official","access":"page","supports":"Revisão de partidas e limitações de versão/plataforma. Reprodução de arquivos não foi testada nesta pesquisa."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002211','zero-cobertura','Construção Zero: cobertura, mobilidade e recursos','lesson','decisions','Uma trilha própria, sem exigir peças ou edição para resolver confrontos e rotações.','Construção Zero compartilha mira, informação e decisão com outras experiências, mas não oferece a construção de peças como resposta. Estude cobertura existente, posição, caminhos e recursos da modalidade. Uma parede do cenário pode bloquear uma linha de visão sem proteger todas as direções. Observe o que acontece se ela deixa de servir como cobertura.

Antes de sair de uma posição, identifique a próxima cobertura, o trecho exposto, a alternativa de retorno e os recursos disponíveis. Um item de movimento pode reduzir exposição e também criar uma chegada previsível. Não liste um item como obrigatório sem confirmar que existe na experiência atual. O mesmo vale para regras de queda, proteções e recarga.

A comunicação oficial da v40.40 documenta mudanças específicas de Construção Zero no Capítulo 7 Temporada 2. Isso mostra por que um tutorial precisa de contexto temporal. Não usamos essas notas para afirmar que todos os efeitos continuam iguais na temporada atual. A listagem oficial descreve a modalidade, mas não substitui verificação de cada parâmetro.

Atividade editorial. Escolha uma gravação própria e pause antes de atravessar um espaço. Marque coberturas, adversários vistos e informação ausente. Proponha duas opções usando somente recursos presentes. Depois revise a chegada: você tinha proteção, visão e uma próxima opção ou ficou sem saída?

Critério. Consiga explicar a relação entre mobilidade e cobertura, distinguindo observação de hipótese. Para evolução, reveja situações comparáveis e mudanças de decisão, sem substituir avaliação por número de partidas. Esta trilha não exige a aula de materiais, Freebuild ou Piece Control.','Curadoria Clutchfolio','https://store.epicgames.com/p/fortnite','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['zero','mid','nivel-3']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":3,"domain":"zero","modes":["zero"],"experience":"all","phase":"mid","prerequisites":["inventario-tempestade","peeks-trocas"],"objectives":["Planejar deslocamento com cobertura e recursos da modalidade.","Identificar regras que precisam de confirmação por versão."],"assessment":["Propor duas rotas sem recorrer a construção.","Explicar a posição de chegada e possibilidade de saída."],"exercise_ids":[],"competency_ids":["zero-cover","zero-movement","zero-resources"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"Fortnite — Epic Games Store","url":"https://store.epicgames.com/p/fortnite","kind":"official","access":"page","supports":"Objetivo do Battle Royale e distinção entre experiências. A listagem contém também textos históricos; não confirma todos os detalhes da interface atual."},{"title":"v40.40 Ato III — notas Epic","url":"https://communities.epicgames.com/thread/v40-40-act-iii-battle-royale-update-notes/0j2r?lang=pt-br","kind":"official","access":"page","supports":"Exemplo histórico de mudanças por modalidade e separação de loot competitivo. Não confirma a manutenção desses parâmetros na temporada atual."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002212','endgame-camadas','Endgame: layers, moving zones e gestão de espaço','lesson','decisions','Separe posição vertical, movimento da zona e recursos antes de praticar as zonas finais.','Late game descreve a fase avançada de uma partida; endgame enfatiza situações decisivas finais. Não existe nesta base um número de zona que separa obrigatoriamente os dois. Moving zones são deslocamentos da área segura quando a experiência os utiliza. Confira o comportamento observado antes de aplicar uma técnica de um vídeo de outra modalidade.

Layer é uma camada de altura e espaço ocupável. Height é uma posição superior relativa; mid-ground e low-ground descrevem posições intermediárias e inferiores. Nenhuma delas garante vantagem em todas as situações. Compare recursos necessários, acesso, exposição, jogadores próximos e capacidade de acompanhar a zona. Mudar de camada pode evitar congestionamento e também criar risco na passagem.

Antes de mover, leia direção, espaço disponível e possibilidades de atravessar. Durante a execução, atualize quem ocupa a frente, acima e abaixo. Em equipe, uma chamada como mudar de camada precisa de destino e confirmação, não apenas do termo. Um jogador pode interpretar outra posição e perder apoio.

Atividade editorial. Em Zone Wars ou numa gravação, pause antes de uma mudança de zona. Marque camada atual, duas possibilidades e recurso crítico. Depois identifique o primeiro sinal de congestionamento ou bloqueio. A ilha de Zone Wars é uma simulação com regras próprias; desempenho nela não comprova classificação num torneio.

Avaliação. Justifique manter ou abandonar uma layer com informação disponível. Registre decisões revisadas e erros específicos de execução. Volume de rodadas não mede domínio de endgame. Para Construção Zero, estude o módulo de rotações finais com cobertura: conceitos espaciais podem ser compartilhados sem exigir construção.','Curadoria Clutchfolio','https://www.fortnite.com/@reisshub/4175-6046-6184','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['phases','endgame','nivel-4']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":4,"domain":"phases","modes":["build"],"experience":"all","phase":"endgame","prerequisites":["mid-rotacoes","materiais-mats","piece-box-realistic"],"objectives":["Distinguir fase final, movimento da zona e camada ocupada.","Avaliar uma mudança de layer pelos custos e opções."],"assessment":["Explicar posição vertical sem afirmar superioridade universal.","Registrar destino e confirmação de uma chamada de equipe."],"exercise_ids":["00000000-0000-4000-8000-000000001005","00000000-0000-4000-8000-000000001006"],"competency_ids":["layers","moving-zone","zone-wars"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"Training Hub V2 — Reisshub","url":"https://www.fortnite.com/@reisshub/4175-6046-6184","kind":"official","access":"listing","supports":"Identidade e código da ilha de treinamento. Os procedimentos desta aula são editoriais; a ilha não foi executada."},{"title":"Como Khanada pratica em 2026 — entrevista Dignitas","url":"https://dignitas.gg/articles/how-fortnite-pros-actually-practice-in-2026-featuring-khanada","kind":"professional","access":"page","supports":"Relato individual de aquecimento, prática e análise. Não estabelece rotina universal, dose ótima ou papéis fixos de uma equipe."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002213','tarp-refresh','Tarpar, tunnels e refresh: problemas diferentes','lesson','mechanics','Construir um caminho protegido não é o mesmo que buscar reposição de recursos.','Tarping, ou tarpar, descreve construir proteção enquanto se desloca; um tunnel é uma configuração de passagem protegida. O objetivo é organizar movimento e linhas de visão, não preencher toda peça possível. A proteção depende do que vem de cada direção e dos recursos disponíveis. Um túnel bonito pode ser inadequado se consome a reserva ou termina num espaço bloqueado.

Refresh é buscar uma renovação de recursos ou possibilidades, frequentemente associada a um confronto e ao que ele oferece. Não é sinônimo de eliminação: o recurso precisa estar acessível e a ação precisa fazer sentido na situação. Planejar a reposição não exige perseguir toda oportunidade aparente. Anote necessidade, risco e condição para desistir.

Prática inicial. Descreva quais direções precisam de proteção numa sequência simples e observe custo e saída. Prática contextual. Acrescente uma mudança de direção e identifique quando parar de construir, reposicionar ou usar outra opção. Como as ilhas não foram executadas nesta pesquisa, use apenas cenários existentes e registre a configuração real.

Em equipe, tarper é uma tarefa de organizar o caminho, não uma identidade permanente. Outra pessoa pode assumir por posição, recursos ou condição. Combine quem conduz, quem acompanha e como comunicar uma interrupção. Um plano de refresh também precisa de responsabilidade e limite, sem obrigar um jogador a ficar separado.

Critério. Na revisão, diferencie falha de execução, falta de informação e escolha de gasto. Identifique uma peça sem função clara ou uma ação de reposição sem saída. Os termos servem para explicar decisões; não são uma receita fixa de endgame nem promessa de sucesso.','Curadoria Clutchfolio','https://www.fortnite.com/@reisshub/4175-6046-6184','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['building','endgame','nivel-4']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":4,"domain":"building","modes":["build"],"experience":"all","phase":"endgame","prerequisites":["endgame-camadas","pecas-edicao"],"objectives":["Diferenciar caminho protegido e reposição de recursos.","Planejar tarefa de tarpar com custo e saída."],"assessment":["Identificar a função de uma proteção e seu gasto.","Descrever necessidade e condição de desistência de um refresh."],"exercise_ids":["00000000-0000-4000-8000-000000001005","00000000-0000-4000-8000-000000001006"],"competency_ids":["tarping","refresh","resources"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"Training Hub V2 — Reisshub","url":"https://www.fortnite.com/@reisshub/4175-6046-6184","kind":"official","access":"listing","supports":"Identidade e código da ilha de treinamento. Os procedimentos desta aula são editoriais; a ilha não foi executada."},{"title":"Como Khanada pratica em 2026 — entrevista Dignitas","url":"https://dignitas.gg/articles/how-fortnite-pros-actually-practice-in-2026-featuring-khanada","kind":"professional","access":"page","supports":"Relato individual de aquecimento, prática e análise. Não estabelece rotina universal, dose ótima ou papéis fixos de uma equipe."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002214','zero-endgame','Endgame de Construção Zero: espaço e opções finais','lesson','decisions','Reveja as zonas finais com cobertura, terreno e mobilidade realmente disponíveis.','No endgame de Construção Zero, planeje com a cobertura e os recursos da experiência. Não tente transferir um tunnel de construção para uma modalidade sem peças. Observe relevo, objetos, ângulos cruzados, adversários conhecidos e espaço necessário para a próxima ação. Uma posição elevada pode oferecer visão e também expor seu movimento.

Quando a área segura muda, a opção mais próxima nem sempre mantém proteção. Antecipe a chegada e a possibilidade de continuar depois dela. Se a experiência tiver zonas móveis, observe o deslocamento real; não use timings de outro formato. Confirme proteções e recursos disponíveis antes de basear a decisão numa mecânica antiga.

Em equipe, combine destino e apoio possível. Quem chegou primeiro pode observar um ângulo, mas isso não garante que os demais possam atravessar. Descreva ameaça e local em vez de apenas mandar avançar. Em Solo, reduza o plano a sinais que consegue acompanhar sem informação de colegas.

Atividade editorial. Pause antes de duas rotações finais de uma gravação. Para cada uma, registre posição inicial, cobertura pretendida, recurso crítico, caminho alternativo e informação ausente. Retome e veja qual condição mudou. Não declare que a decisão foi correta somente porque a partida terminou em vitória.

Avaliação. Compare a qualidade das justificativas e as opções preservadas em situações semelhantes. Se os cenários diferem demais, apresente casos separados em vez de criar uma média universal. A tarefa conclui quando existe uma observação e uma alteração testável, sem obrigação de jogar mais partidas naquele dia.','Curadoria Clutchfolio','https://store.epicgames.com/p/fortnite','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['zero','endgame','nivel-4']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":4,"domain":"zero","modes":["zero"],"experience":"all","phase":"endgame","prerequisites":["zero-cobertura","mid-rotacoes"],"objectives":["Adaptar leitura de espaço às zonas finais sem construção.","Preservar opções depois da posição de chegada."],"assessment":["Revisar duas rotações finais com alternativas contextualizadas.","Separar condição observada de suposição sobre o adversário."],"exercise_ids":["00000000-0000-4000-8000-000000001006"],"competency_ids":["zero-endgame","zero-position","zero-rotation"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"Fortnite — Epic Games Store","url":"https://store.epicgames.com/p/fortnite","kind":"official","access":"page","supports":"Objetivo do Battle Royale e distinção entre experiências. A listagem contém também textos históricos; não confirma todos os detalhes da interface atual."},{"title":"Replays e versões — suporte Epic","url":"https://www.epicgames.com/help/c-34254770/c-33726977/a25553277?lang=pt-BR","kind":"official","access":"page","supports":"Revisão de partidas e limitações de versão/plataforma. Reprodução de arquivos não foi testada nesta pesquisa."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002215','equipe-funcoes','Equipe: IGL, co-IGL, fragger e tarefas temporárias','lesson','decisions','Um vocabulário editorial para distribuir decisões e tarefas sem impor posições rígidas.','IGL é uma forma comum de nomear quem conduz decisões e chamadas. Co-IGL descreve apoio nessa condução. Fragger costuma enfatizar ações de combate; support enfatiza suporte às necessidades da equipe. Aqui usamos essas definições como organização editorial de tarefas, não como uma escala oficial ou atribuição a um profissional específico.

Tarper e responsável por uma ação de refresh são tarefas de uma situação. Posição, informação, recursos e disponibilidade podem mudar quem executa. Não presuma que uma dupla ou trio tenha sempre os mesmos papéis. Em Solo, as tarefas se concentram no próprio jogador; isso não torna o jogador um elenco de posições formais.

Uma chamada útil contém situação, intenção e informação necessária para executar. Por exemplo editorial: preciso mudar de posição; há pressão do lado indicado; vocês conseguem acompanhar pelo caminho descrito? A confirmação serve para atualizar o plano, não para transferir culpa. Se duas chamadas entram em conflito, combine previamente como resolver e revise depois o contexto.

Atividade. Na revisão de uma partida da equipe, marque uma chamada, a informação em que se apoiou e a resposta de cada pessoa. Identifique quem tinha melhor visão para decidir naquele momento. Reescreva uma comunicação confusa com destino, condição e confirmação. Não classifique a pessoa por um único erro.

Limite da pesquisa. A entrevista de Khanada sustenta a importância de prática e análise no relato dele; não documenta todos esses papéis nem valida este exercício. Não atribuímos funções a equipes atuais sem fonte específica. O resultado avaliado é clareza e coordenação observáveis, não uma nota universal de liderança.','Curadoria Clutchfolio','https://dignitas.gg/articles/how-fortnite-pros-actually-practice-in-2026-featuring-khanada','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['team','review','nivel-4']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":4,"domain":"team","modes":["build","zero"],"experience":"all","phase":"review","prerequisites":["mid-rotacoes"],"objectives":["Distinguir condução de decisão, combate e tarefas contextuais.","Construir uma chamada com intenção e confirmação."],"assessment":["Revisar uma comunicação sem atribuir papéis rígidos.","Identificar quem tinha informação útil para a decisão."],"exercise_ids":["00000000-0000-4000-8000-000000001102"],"competency_ids":["duo","information","resources"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"Como Khanada pratica em 2026 — entrevista Dignitas","url":"https://dignitas.gg/articles/how-fortnite-pros-actually-practice-in-2026-featuring-khanada","kind":"professional","access":"page","supports":"Relato individual de aquecimento, prática e análise. Não estabelece rotina universal, dose ótima ou papéis fixos de uma equipe."},{"title":"Replays e versões — suporte Epic","url":"https://www.epicgames.com/help/c-34254770/c-33726977/a25553277?lang=pt-BR","kind":"official","access":"page","supports":"Revisão de partidas e limitações de versão/plataforma. Reprodução de arquivos não foi testada nesta pesquisa."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002216','reload-retornos','Reload / Trocação Reload: decisões com retornos','lesson','decisions','Conheça a experiência sem confundir Reload com uma terceira regra de construção.','Reload é uma experiência de Battle Royale com um sistema de retornos e versões com e sem construção. Trocação é o nome usado na comunicação brasileira atual da Epic para Zero Build; Trocação Reload identifica a variante sem construção de Reload. Não use Reload e Trocação como sinônimos: um nome descreve a experiência, o outro descreve a ausência de construção no contexto citado.

A listagem oficial consultada descreve Solo, Duplas e Esquadrões. Isso não comprova que toda fila está disponível em todo horário, região ou evento, nem que Trios exista ali. Confira o lobby e o regulamento de uma competição específica. Não copiamos horários, número de retornos ou condições antigas como regras universais.

Planejamento editorial. Antes de uma luta, identifique o que a experiência permite após uma eliminação e o que encerra a participação. Em equipe, sobreviver para manter uma possibilidade de retorno pode disputar prioridade com tentar uma troca imediata. A escolha depende da regra observada e da situação, não de uma obrigação de agressividade.

Atividade. Registre uma sequência com eliminação ou retorno e descreva quais opções existiam para a pessoa e para a equipe. Separe a informação disponível antes do confronto do que soube depois. Compare uma decisão de proteção com uma de combate, utilizando somente as condições daquela partida.

Próximo estudo. Para a variante com construção, use também a trilha de peças e mats; para a variante sem construção, cobertura e mobilidade. Fundamentos de informação e comunicação são compartilhados. O conteúdo não cria matchmaking, não acessa a conta Epic e não prova que uma rotina de Battle Royale transfere integralmente para Reload.','Curadoria Clutchfolio','https://store.epicgames.com/p/fortnite--reload','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['foundations','foundation','nivel-1']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":1,"domain":"foundations","modes":["build","zero"],"experience":"reload","phase":"foundation","prerequisites":["inventario-tempestade"],"objectives":["Distinguir experiência Reload e variante sem construção.","Considerar condições de retorno no planejamento."],"assessment":["Descrever a fila e as regras observadas naquela partida.","Justificar uma decisão de equipe diante de uma possibilidade de retorno."],"exercise_ids":[],"competency_ids":["information","resources"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"Fortnite Reload — Epic Games Store","url":"https://store.epicgames.com/p/fortnite--reload","kind":"official","access":"page","supports":"Reload com e sem construção; descrição atual lista Solo, Duplas e Esquadrões e sistema de retornos. Disponibilidade deve ser conferida no lobby."},{"title":"Guia do Modo Ranqueado — Epic","url":"https://www.fortnite.com/competitive/discover-competitive/fortnite-ranked-play-explained?lang=pt-BR&region=NAC","kind":"official","access":"page","supports":"Experiências ranqueadas e orientação de acesso. Não fornece fórmula reproduzível de pontos; não usamos tabela histórica como requisito universal."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002217','ranked-scrims-torneios','Casual, Ranked, scrims e torneios: contextos diferentes','lesson','competitive','Aprenda a consultar regras do evento sem transformar uma temporada em regra geral.','Casual e Ranked oferecem contextos distintos para partidas; ranque não é um certificado universal de todas as habilidades. Scrims são atividades organizadas de prática, com condições e regras do organizador. Custom Matches são uma forma de partida privada, não um selo de torneio oficial. A criação de partidas privadas depende de habilitação pela Epic; o Clutchfolio não fornece essa integração.

FNCS e Cash Cups precisam de identificação de evento, região e versão do regulamento. A FNCS 2026 possui documentação do circuito Duplas e um regulamento separado de FNCS Solo. Portanto, dizer apenas FNCS não basta para definir tamanho de equipe, pontuação ou classificação. Não transportamos prêmios e requisitos de um evento para outro.

Checklist editorial. Abra a fonte oficial vinculada ao evento. Confira modalidade, região, sessão, elegibilidade, formato, pontuação, critérios de avanço e anexos. Diferencie a data de publicação do regulamento do horário da sessão. Para idade, responsável, conta e autenticação, leia regras gerais e eventuais requisitos adicionais; nunca envie credenciais para o assistente.

Planejamento. Escolha uma habilidade que o contexto permite observar. Ranked pode oferecer uma situação de decisão; scrims podem permitir revisão coletiva; um mapa pode isolar execução. Nenhum substitui todas as condições de torneio. Antes de entrar numa comunidade, confira regras, moderação e condições de participação. Não afirmamos ter validado servidores ou organizadores no jogo.

Avaliação. Descreva de qual evento veio cada requisito e onde confirmou a regra. Se a informação não estiver disponível, marque pendência. O plano de preparação permanece editável e não promete classificação. Esta aula não publica uma agenda de próximos campeonatos nem uma tabela única de pontuação.','Curadoria Clutchfolio','https://www.fortnite.com/competitive/discover-competitive/fortnite-ranked-play-explained?lang=pt-BR&region=NAC','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['competitive','review','nivel-4']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":4,"domain":"competitive","modes":["build","zero"],"experience":"all","phase":"review","prerequisites":["primeira-partida","mid-rotacoes"],"objectives":["Distinguir prática organizada e competição oficial.","Localizar requisitos no regulamento do evento correto."],"assessment":["Identificar modo, região e fase com fonte própria.","Marcar um requisito ausente em vez de deduzi-lo de outra temporada."],"exercise_ids":["00000000-0000-4000-8000-000000001103","00000000-0000-4000-8000-000000001104"],"competency_ids":["ranked","scrims","tournament-prep"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"Guia do Modo Ranqueado — Epic","url":"https://www.fortnite.com/competitive/discover-competitive/fortnite-ranked-play-explained?lang=pt-BR&region=NAC","kind":"official","access":"page","supports":"Experiências ranqueadas e orientação de acesso. Não fornece fórmula reproduzível de pontos; não usamos tabela histórica como requisito universal."},{"title":"Partidas privadas — suporte Epic","url":"https://www.epicgames.com/help/c-34406160/c-43130556/a15436613","kind":"official","access":"page","supports":"Criação requer conta habilitada em programa de criadores; região e modo precisam corresponder. Não há integração de matchmaking do Clutchfolio."},{"title":"FNCS 2026 — regras do circuito Duplas","url":"https://www.fortnite.com/competitive/rules-guidelines/rules-library/fortnite-championship-series-fncs-2026-official-rules/?region=NAC","kind":"official","access":"page","supports":"Regulamento específico descreve Duplas/Battle Royale; não se aplica automaticamente à FNCS Solo nem a outros torneios."},{"title":"FNCS Solo 2026 — regras em português","url":"https://www.fortnite.com/competitive/rules-guidelines/rules-library/fortnite-championship-series-fncs-solos-2026-official-rules?lang=pt-BR&region=NAC","kind":"official","access":"page","supports":"Evento Solo separado, fases, anexos e vínculo com regras gerais. Verifique revisões, região e evento antes de participar."},{"title":"Regras Gerais do Fortnite Competitivo","url":"https://www.fortnite.com/competitive/rules-guidelines/rules-library/fortnite-competitive-master-rules","kind":"official","access":"page","supports":"Requisitos gerais de conta, idade, responsável e autenticação. Requisitos adicionais pertencem ao regulamento de cada evento."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002218','surge-contexto','Storm Surge: conceito histórico e verificação obrigatória','lesson','competitive','Estude o conceito sem ensinar limiares antigos como parâmetros de 2026.','Storm Surge é uma mecânica documentada pela Epic para situações com muitos jogadores restantes, associada a dano causado e redução dessa concentração. O comunicado consultado é de 2022 e contém valores daquela época. Um relato de Bugha em 2023 também trata do problema. Nenhuma dessas fontes confirma parâmetros de todos os eventos atuais.

Por isso, esta aula é de análise histórica e preparação da verificação, não um guia de números vigentes. Não publicamos quantidade de jogadores por zona, dano periódico, duração nem ativação garantida. Antes de aplicar uma leitura, confira a modalidade, o evento, a versão e o que a interface realmente informa.

Questão editorial. Se a mecânica estiver confirmada para a situação estudada, observe como informação, posição e oportunidades de dano se relacionam com a restrição apresentada. Isso difere de escolher uma fight para eliminação e de buscar refresh por recursos. Os três problemas podem aparecer juntos, mas seus objetivos não são iguais.

Atividade. Em uma gravação autorizada com contexto conhecido, pause antes de uma decisão relacionada à mecânica. Anote data ou versão, aviso visível, informação disponível, alternativas e custo de exposição. Se não houver contexto ou indicação suficiente, registre que o caso não permite avaliar Storm Surge. Não complete a lacuna com uma tabela de outra temporada.

Avaliação. A habilidade inicial é reconhecer o limite da informação e separar o conceito do parâmetro. Uma recomendação atribuída a Bugha deve permanecer identificada como relato histórico, sem afirmar que ele mantém a mesma estratégia hoje. A conclusão do estudo não exige jogar uma quantidade maior de horas ou buscar confrontos sem objetivo.','Curadoria Clutchfolio','https://www.fortnite.com/news/fortnite-chapter-3-season-3-competitive-storm-surge-update','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['competitive','endgame','nivel-5']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":5,"domain":"competitive","modes":["build"],"experience":"all","phase":"endgame","prerequisites":["endgame-camadas","ranked-scrims-torneios"],"objectives":["Distinguir conceito histórico e parâmetros atuais não confirmados.","Separar surge, confronto e reposição de recursos."],"assessment":["Identificar versão e evidência antes de interpretar um caso.","Recusar limiares antigos quando faltar confirmação atual."],"exercise_ids":["00000000-0000-4000-8000-000000001006"],"competency_ids":["surge","information"],"meta_scope":"Conteúdo histórico de 2022–2023. Limiares, dano e ativação em 2026 não foram confirmados nesta pesquisa; não usar como regulamento vigente.","classification":"editorial","sources":[{"title":"Storm Surge — comunicado Epic de 2022","url":"https://www.fortnite.com/news/fortnite-chapter-3-season-3-competitive-storm-surge-update","kind":"official","access":"page","supports":"Definição histórica da mecânica e demonstração de que parâmetros mudam. Valores de 2022 NÃO são tratados como vigentes."},{"title":"Storm Surge — relato de Bugha em 2023","url":"https://dignitas.gg/articles/fortnite-storm-surge-survival-guide-bughas-tips-on-how-to-survive-to-the-endgame","kind":"professional","access":"page","supports":"Relato histórico sobre informação e posicionamento; não confirma ativação, limiares ou meta em 2026."}]}'::jsonb) on conflict do nothing;
insert into public.articles(id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published,topic,tags,evidence,source_published_at,curriculum) values('00000000-0000-4000-8000-000000002219','vod-hipoteses','VOD Review avançado: hipóteses, retenção e transferência','lesson','vod','Transforme um padrão observado em prática testável, preservando incerteza e contexto.','Revisão própria começa antes de conhecer o resultado da decisão. Pause, registre informação disponível, alternativas e intenção. Depois observe a execução e o desfecho. Erro mecânico, leitura incompleta e escolha tática são explicações diferentes; o vídeo pode não revelar tudo. Uma derrota isolada não permite concluir que uma habilidade regrediu.

Revisão de profissionais pode oferecer perguntas e exemplos, mas exige contexto: modalidade, temporada, formato, recursos, qualidade do lobby e objetivo. Ver um movimento sem essa informação não permite copiar sua razão. Nesta pesquisa, não assistimos nem analisamos audiovisualmente vídeos completos. As referências textuais e listagens têm seus níveis de acesso identificados.

Ciclo editorial. Escolha um padrão observado em casos semelhantes. Formule uma hipótese e uma tarefa, mantenha condições comparáveis no teste e depois procure a aplicação numa partida. Retenção é conseguir executar depois de um intervalo; transferência é usar a habilidade em outra situação. Melhor pontuação imediatamente após repetir um cenário não demonstra sozinho as duas.

A pesquisa científica consultada inclui aprendizagem em esportes e distribuição de prática em MOBA. Essas fontes ajudam a organizar perguntas; não determinam dose ótima de Fortnite nem comprovam esta metodologia. Ajuste a sessão à disponibilidade, atenção e conforto. Mais tempo registrado não é prova de evolução.

Registro. Mantenha data, cenário, configuração, observação, hipótese e próxima ação. Se a atualização impedir abrir o replay, utilize notas ou gravação autorizada já disponível e indique a limitação. Revise a rotina a partir dos resultados comparáveis; quando houver poucos dados, diga que ainda não é possível avaliar a mudança.','Curadoria Clutchfolio','https://www.epicgames.com/help/c-34254770/c-33726977/a25553277?lang=pt-BR','2026-10-10T12:00:00Z','2026-10-10T12:00:00Z','2026-11-10T00:00:00Z',true,'guides',array['review','review','nivel-5']::text[],'analysis',null,'{"version":"mastery-2026-10-10.1","level":5,"domain":"review","modes":["build","zero"],"experience":"all","phase":"review","prerequisites":["mid-rotacoes","mira-movimento"],"objectives":["Converter observação em hipótese e tarefa testável.","Separar desempenho imediato, retenção e transferência."],"assessment":["Registrar evidência e incerteza de uma decisão.","Definir uma reavaliação sem prescrever dose perfeita de treino."],"exercise_ids":["00000000-0000-4000-8000-000000001006"],"competency_ids":["self-review","pro-review","pattern-review"],"meta_scope":"Fundamentos editoriais. Disponibilidade de itens, limites, interface e regras precisam ser conferidos na modalidade e versão praticadas.","classification":"editorial","sources":[{"title":"Replays e versões — suporte Epic","url":"https://www.epicgames.com/help/c-34254770/c-33726977/a25553277?lang=pt-BR","kind":"official","access":"page","supports":"Revisão de partidas e limitações de versão/plataforma. Reprodução de arquivos não foi testada nesta pesquisa."},{"title":"Intervenções de aquisição de habilidades — revisão de escopo","url":"https://pubmed.ncbi.nlm.nih.gov/38401870/","kind":"scientific","access":"abstract","supports":"Mapeia intervenções e limitações de retenção/transferência em esportes; adaptação ao Fortnite é editorial."},{"title":"Mind the gap — prática distribuída em MOBA","url":"https://pubmed.ncbi.nlm.nih.gov/36240151/","kind":"scientific","access":"abstract","supports":"Associação observacional em outro jogo; não demonstra causalidade nem duração ideal para Fortnite."},{"title":"Como Khanada pratica em 2026 — entrevista Dignitas","url":"https://dignitas.gg/articles/how-fortnite-pros-actually-practice-in-2026-featuring-khanada","kind":"professional","access":"page","supports":"Relato individual de aquecimento, prática e análise. Não estabelece rotina universal, dose ótima ou papéis fixos de uma equipe."}]}'::jsonb) on conflict do nothing;
